ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportRejestryKasowoBankowe]
	@rowVersion bigint,
	@pointOfSaleId int
AS
BEGIN
	SET NOCOUNT ON;
	
	select
		(select max(KAR_CzasModyfikacji) from cdn.Rejestry join cdn.picostanowiskaformypl on PFP_KARNumer = KAR_GIDNumer where PFP_PSaID = @pointOfSaleId) as [@RowVersion], (		
			select distinct kar_gidnumer as [@Id], 
				kar_seria as [@Code], 
				kar_nazwa as [@Name], 
				(select WaN_ID from cdn.walnag where WaN_Symbol = kar_waluta) as [@CurrencyId], 
				kar_typ - 1 as [@Type],
				'true' as [@IsActive]
			from cdn.pos_KarDoEksportu(@pointOfSaleId,0) --@rowVersion
			join cdn.Rejestry on KAR_GIDNumer=karnumer
		for xml path('CashBankAccount'), type)
	for xml path('CashBankAccounts')
	SET NOCOUNT OFF;	
END
